53	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
54	  const router = useRouter()
55	  const searchParams = useSearchParams()
56	
57	  const [clients, setClients] = useState<Client[]>(initialClients)
58	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
59	  const [selectedIds, setSelectedIds] = useState<string[]>([])
60	  const [loading, setLoading] = useState(false)
61	  const [fetchError, setFetchError] = useState<Error | null>(null)
62	  const [drawerOpen, setDrawerOpen] = useState(false)
63	  const [editingClient, setEditingClient] = useState<Client | null>(null)
64	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
65	  const [page, setPage] = useState(1)
66	  const [hasMore, setHasMore] = useState(false)
67	  const [totalCount, setTotalCount] = useState<number | null>(null)
68	
69	  // Saved views
70	  const [views, setViews] = useState<ClientView[]>([])
71	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
72	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
73	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
74	  const [editingView, setEditingView] = useState<ClientView | null>(null)
75	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
76	
77	  const fetchViews = useCallback(async () => {
78	    try {
79	      const res = await fetch('/api/client-views')
80	      if (res.ok) {
81	        const json = await res.json() as { data: ClientView[] }
82	        setViews(json.data ?? [])
83	        // Auto-activate first system default view
84	        const defaultView = json.data?.find((v) => v.is_default)
85	        if (defaultView) {
86	          setActiveViewId((prev) => prev ?? defaultView.id)
87	        }
88	      }
89	    } catch {
90	      toast.error('Failed to load views', { description: 'Using All clients as default' })
91	    }
92	  }, [])
93	
94	  // Load saved views on mount
95	  useEffect(() => {
96	    void fetchViews()
97	  }, [fetchViews])
98	
99	  // Restore page from URL
100	  useEffect(() => {
101	    const p = parseInt(searchParams.get('page') ?? '1', 10)
102	    if (p > 1) {
103	      setPage(p)
104	    }
105	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
106	
107	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
108	    setLoading(true)
109	    setFetchError(null)
110	    try {
111	      const params = new URLSearchParams()
112	      if (f.q) params.set('q', f.q)
113	      if (f.tags.length) params.set('tags', f.tags.join(','))
114	      if (f.vip) params.set('vip', 'true')
115	      if (f.inactive) params.set('inactive', 'true')
116	      if (f.noShows) params.set('no_show', 'true')
117	      if (!f.showArchived) params.set('archived', 'false')
118	      else params.set('archived', 'any')
119	      if (f.spendingTier) params.set('spending', f.spendingTier)
120	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
121	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
122	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
123	      params.set('page', String(p))
124	      params.set('per_page', '50')
125	
126	      const res = await fetch(`/api/clients?${params.toString()}`)
127	      if (!res.ok) throw new Error('Failed to load clients')
128	      const json = await res.json() as { data: Client[]; count: number }
129	
130	      if (p === 1) {
131	        setClients(json.data ?? [])
132	      } else {
133	        setClients((prev) => [...prev, ...(json.data ?? [])])
134	      }
135	      setTotalCount(json.count ?? null)
136	      setHasMore((json.data?.length ?? 0) >= 50)
137	    } catch (err) {
138	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
139	    } finally {
140	      setLoading(false)
141	    }
142	  }, [])
143	
144	  useEffect(() => {
145	    void fetchClients(filters, 1)
146	    setPage(1)
147	    setSelectedIds([])
148	  }, [filters, fetchClients])
149	
150	  function handleFiltersChange(f: ClientFilters) {
151	    setFilters(f)
152	    setHasUnsavedChanges(true)
153	  }
154	
155	  function handleViewChange(viewId: string | null) {
156	    setActiveViewId(viewId)
157	    setHasUnsavedChanges(false)
158	    const view = views.find((v) => v.id === viewId)
159	    if (view) {
160	      // Apply view filters
161	      const viewFilters = view.filters as Partial<ClientFilters>
162	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
163	    } else {
164	      setFilters(DEFAULT_FILTERS)
165	    }
166	  }
167	
168	  async function handleDeleteView(viewId: string) {
169	    try {
170	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
171	      if (!res.ok) throw new Error('Failed to delete view')
172	      setViews((prev) => prev.filter((v) => v.id !== viewId))
173	      if (activeViewId === viewId) {
174	        const defaultView = views.find((v) => v.is_default)
175	        setActiveViewId(defaultView?.id ?? null)
176	      }
177	      toast.success('View deleted')
178	    } catch {
179	      toast.error('Failed to delete view')
180	    }
181	  }
182	
183	  async function handleDuplicateView(view: ClientView) {
184	    try {
185	      const res = await fetch('/api/client-views', {
186	        method: 'POST',
187	        headers: { 'Content-Type': 'application/json' },
188	        body: JSON.stringify({
189	          name: `${view.name} (copy)`,
190	          filters: view.filters,
191	          scope: 'private',
192	        }),
193	      })
194	      if (!res.ok) throw new Error('Failed to duplicate view')
195	      const json = await res.json() as { data: ClientView }
196	      setViews((prev) => [...prev, json.data])
197	      toast.success('View duplicated')
198	    } catch {
199	      toast.error('Failed to duplicate view')
200	    }
201	  }
202	
203	  function handleViewSaved(savedView: ClientView) {
204	    setViews((prev) => {
205	      const idx = prev.findIndex((v) => v.id === savedView.id)
206	      if (idx >= 0) {
207	        const next = [...prev]
208	        next[idx] = savedView
209	        return next
210	      }
211	      return [...prev, savedView]
212	    })
213	    setActiveViewId(savedView.id)
214	    setHasUnsavedChanges(false)
215	  }
216	
217	  function handleLoadMore() {
218	    const nextPage = page + 1
219	    setPage(nextPage)
220	    router.replace(`?page=${nextPage}`, { scroll: false })
221	    void fetchClients(filters, nextPage)
222	  }
223	
224	  function handleEditClient(client: Client) {
225	    setEditingClient(client)
226	    setDrawerOpen(true)
227	  }
228	
229	  function handleNewClient() {
230	    setEditingClient(null)
231	    setDrawerOpen(true)
232	  }
233	
234	  function handleDrawerSuccess(client: Client) {
235	    setClients((prev) => {
236	      const idx = prev.findIndex((c) => c.id === client.id)
237	      if (idx >= 0) {
238	        const next = [...prev]
239	        next[idx] = client
240	        return next
241	      }
242	      return [client, ...prev]
243	    })
244	  }
245	
246	  const hasActiveFilters = !!(
247	    filters.q || filters.tags.length > 0 || filters.vip ||
248	    filters.inactive || filters.noShows || filters.spendingTier ||
249	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
250	  )
251	
252	  const inactiveCount = useMemo(() => {
253	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
254	    return clients.filter(
255	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
256	    ).length
257	  }, [clients])
258	
259	  const activeView = views.find((v) => v.id === activeViewId) ?? null
260	  const isInitialLoad = loading && clients.length === 0
261	
262	  return (
263	    <PullToRefresh
264	      onRefresh={async () => { router.refresh() }}
265	      className="flex flex-col flex-1 overflow-hidden h-full"
266	    >
267	    <div className="flex flex-col gap-4 p-4 lg:p-6">
268	      {/* Header */}
269	      <div className="flex items-center justify-between">
270	        <div className="flex items-center gap-3">
271	          <div>
272	            <Typography variant="h1">Clients</Typography>
273	            <p className="text-sm text-muted-foreground mt-0.5">
274	              {totalCount !== null ? (
275	                <span className="tabular-nums">
276	                  {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
277	                </span>
278	              ) : clients.length > 0 ? (
279	                <span className="tabular-nums">{clients.length} client{clients.length !== 1 ? 's' : ''}</span>
280	              ) : null}
281	            </p>
282	          </div>
283	          {inactiveCount > 0 && (
284	            <span
285	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
286	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-xs font-medium px-2 py-0.5 select-none"
287	            >
288	              <span className="h-2 w-2 rounded-full bg-destructive shrink-0" aria-hidden="true" />
289	              {inactiveCount} inactive
290	            </span>
291	          )}
292	        </div>
293	        <Button onClick={handleNewClient}>
294	          <Plus className="mr-2 h-4 w-4" aria-hidden="true" />
295	          New client
296	        </Button>
297	      </div>
298	
299	      {/* Saved views switcher */}
300	      {views.length > 0 && (
301	        <SavedViewSwitcher
302	          views={views}
303	          activeViewId={activeViewId}
304	          onViewChange={handleViewChange}
305	          onCreateView={() => {
306	            setViewManagerMode('create')
307	            setEditingView(null)
308	            setViewManagerOpen(true)
309	          }}
310	          onEditView={(view) => {
311	            setViewManagerMode('edit')
312	            setEditingView(view)
313	            setViewManagerOpen(true)
314	          }}
315	          onDuplicateView={handleDuplicateView}
316	          onDeleteView={handleDeleteView}
317	        />
318	      )}
319	
320	      {/* Unsaved changes banner */}
321	      {hasUnsavedChanges && activeView && !activeView.is_system && (
322	        <Alert className="py-2 border-warning/30 bg-warning/5">
323	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
324	            <span className="text-warning dark:text-warning-foreground">
325	              Unsaved changes. Save view or discard?
326	            </span>
327	            <div className="flex gap-2 shrink-0">
328	              <Button
329	                size="sm"
330	                variant="outline"
331	                className="h-6 text-xs px-2"
332	                onClick={() => {
333	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
334	                  setHasUnsavedChanges(false)
335	                }}
336	              >
337	                Discard
338	              </Button>
339	              <Button
340	                size="sm"
341	                className="h-6 text-xs px-2"
342	                onClick={() => {
343	                  setViewManagerMode('edit')
344	                  setEditingView(activeView)
345	                  setViewManagerOpen(true)
346	                }}
347	              >
348	                Save view
349	              </Button>
350	            </div>
351	          </AlertDescription>
352	        </Alert>
353	      )}
354	
355	      <ClientFilterBar
356	        filters={filters}
357	        onChange={handleFiltersChange}
358	        tagLibrary={tagLibrary}
359	      />
360	
361	      {selectedIds.length > 0 && (
362	        <BulkActionsBar
363	          selectedIds={selectedIds}
364	          tagLibrary={tagLibrary}
365	          onClearSelection={() => setSelectedIds([])}
366	          onArchived={() => void fetchClients(filters, 1)}
367	          onTagsApplied={() => void fetchClients(filters, 1)}
368	        />
369	      )}
370	
371	      <DataState
372	        data={clients}
373	        isLoading={isInitialLoad}
374	        isError={!!fetchError && clients.length === 0}
375	        error={fetchError}
376	        loadingSlot={<TableSkeleton rows={8} />}
377	        emptySlot={
378	          hasActiveFilters ? (
379	            <EmptyState
380	              icon={SearchX}
381	              title="No clients match these filters"
382	              description="Try different filters or clear all to see everyone."
383	              cta={{ label: 'Clear filters', onClick: () => { setFilters(DEFAULT_FILTERS); setHasUnsavedChanges(false) } }}
384	              variant="no-results"
385	            />
386	          ) : activeView && activeViewId ? (
387	            <EmptyState
388	              icon={BookmarkX}
389	              title="No clients in this view"
390	              description={`The filters in "${activeView.name}" returned no results.`}
391	              cta={{
392	                label: 'Edit view filters',
393	                onClick: () => {
394	                  setViewManagerMode('edit')
395	                  setEditingView(activeView)
396	                  setViewManagerOpen(true)
397	                },
398	              }}
399	              variant="no-results"
400	            />
401	          ) : (
402	            <EmptyState
403	              icon={Users}
404	              title="No clients yet"
405	              description="Add your first client or import from CSV — they'll show up here as they book."
406	              cta={{ label: '+ Add client', onClick: handleNewClient }}
407	              variant="first-time"
408	            />
409	          )
410	        }
411	        errorSlot={
412	          <PageError
413	            error={fetchError ?? new Error('Failed to load clients')}
414	            reset={() => void fetchClients(filters, 1)}
415	            variant="inline"
416	          />
417	        }
418	      >
419	        {(data) => (
420	          <ClientsTable
421	            clients={data}
422	            tagLibrary={tagLibrary}
423	            loading={loading && data.length === 0}
424	            selectedIds={selectedIds}
425	            onSelectionChange={setSelectedIds}
426	            onEdit={handleEditClient}
427	            onAddNote={(id) => setNoteClientId(id)}
428	          />
429	        )}
430	      </DataState>
431	
432	      {/* Load more */}
433	      {(hasMore || loading) && clients.length > 0 && (
434	        <div className="flex items-center justify-between py-4">
435	          <span className="text-sm text-muted-foreground tabular-nums">
436	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
437	          </span>
438	          {hasMore && (
439	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
440	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
441	              Load more
442	            </Button>
443	          )}
444	        </div>
445	      )}
446	
447	      <ClientDrawer
448	        open={drawerOpen}
449	        onOpenChange={(v) => {
450	          setDrawerOpen(v)
451	          if (!v) setEditingClient(null)
452	        }}
453	        client={editingClient}
454	        tagLibrary={tagLibrary}
455	        onSuccess={handleDrawerSuccess}
456	      />
457	
458	      {noteClientId && (
459	        <AddNoteModal
460	          open={Boolean(noteClientId)}
461	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
462	          clientId={noteClientId}
463	        />
464	      )}
465	
466	      <SavedViewManager
467	        open={viewManagerOpen}
468	        onOpenChange={setViewManagerOpen}
469	        mode={viewManagerMode}
470	        view={editingView}
471	        currentFilters={filters}
472	        onSaved={handleViewSaved}
473	      />
474	    </div>
475	    </PullToRefresh>
476	  )
477	}
